// Parse Telegram message: ligne 1 = URL YouTube, ligne 2+ = brief utilisateur schoolsWP.
const messageText = ($input.item.json.message && $input.item.json.message.text) || '';
if (!messageText.trim()) {
  throw new Error('Message Telegram vide. Format attendu: ligne 1 = URL YouTube, ligne 2+ = brief.');
}

const lines = messageText.split('\n').map(l => l.trim()).filter(Boolean);
const yt_url = lines[0] || '';
const user_brief = lines.slice(1).join(' ') || '(aucun brief fourni)';

if (!/youtu\.?be/i.test(yt_url)) {
  throw new Error('Premiere ligne ne ressemble pas a une URL YouTube. Recue: ' + yt_url);
}

const chat_id = $input.item.json.message.chat.id;
const from = ($input.item.json.message.from && $input.item.json.message.from.username) || 'unknown';

return { json: { yt_url, user_brief, chat_id, from } };

// Extract YouTube video ID from URL.
const url = $input.item.json.yt_url || '';
let videoId = null;

const youtuBe = url.match(/youtu\.be\/([A-Za-z0-9_-]{6,})/);
if (youtuBe) videoId = youtuBe[1];

if (!videoId) {
  const watch = url.match(/[?&]v=([A-Za-z0-9_-]{6,})/);
  if (watch) videoId = watch[1];
}

if (!videoId) {
  const shorts = url.match(/youtube\.com\/shorts\/([A-Za-z0-9_-]{6,})/);
  if (shorts) videoId = shorts[1];
}

if (!videoId) throw new Error('Impossible d extraire le videoId depuis: ' + url);

return { json: { ...$input.item.json, video_id: videoId } };

// Parse DataForSEO YouTube subtitles response.
// Structure: { tasks: [{ result: [{ items: [{ subtitles: [{ text, start_time, duration }] }] }] }] }
const raw = $input.item.json;

if (!raw || !Array.isArray(raw.tasks) || !raw.tasks.length) {
  throw new Error('DataForSEO: tasks manquantes dans la reponse. Status: ' + (raw && raw.status_message || 'inconnu'));
}

const task = raw.tasks[0];
if (task.status_code && task.status_code !== 20000) {
  throw new Error('DataForSEO task error ' + task.status_code + ': ' + (task.status_message || 'unknown'));
}

if (!Array.isArray(task.result) || !task.result.length) {
  throw new Error('DataForSEO: aucun result. video_id probablement sans sous-titres disponibles.');
}

const items = task.result[0] && task.result[0].items;
if (!Array.isArray(items) || !items.length) {
  throw new Error('DataForSEO: aucun items dans result[0]. La video n a probablement pas de captions.');
}

// items[0].subtitles ou items est directement la liste de subtitles
let segs = [];
if (Array.isArray(items[0].subtitles)) {
  segs = items[0].subtitles;
} else {
  // fallback : items eux-memes sont les segments
  segs = items.filter(i => i && (i.text || i.snippet));
}

if (!segs.length) {
  throw new Error('DataForSEO: liste subtitles vide. La video n a probablement pas de captions.');
}

let text = segs
  .map(s => (s && (s.text || s.snippet) || '').toString().trim())
  .filter(Boolean)
  .join(' ');

text = text
  .replace(/&amp;#39;|&#39;/g, "'")
  .replace(/&quot;|&#34;/g, '"')
  .replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ')
  .trim();

const word_count = text.split(/\s+/).filter(Boolean).length;

return { json: { clean_transcript: text, word_count, segments: segs.length, source: 'dataforseo' } };

